t.guides["forever/horde/30-40/02-thousand-needles"] = (function() return {
		["Clam beds"] = "Bancs de praires",
		["Head north up the coast. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach; open each clam in your bags for its meat."] = "Remontez la côte vers le nord. Les Praires géantes reposent dans les hauts-fonds et les Clampants des récifs enragés parcourent la plage ; ouvrez chaque praire dans vos sacs pour récupérer sa chair.",
		["On the top floor"] = "Au dernier étage",
		["Underwater"] = "Sous l'eau",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["{npc:5641}'s next errand sends you after a demon lord with an elite guard: skip it."] = "La mission suivante de {npc:5641} vous envoie contre un seigneur démon escorté d'élites : passez-la.",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892} se tient dans {object:172957}.",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901} : {npc:3527} et votre {item:5177}",
		["{npc:5905}: your {item:5178}"] = "{npc:5905} : votre {item:5178}",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
} end)()
t.guides["forever/horde/30-40/03-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "Retournez au camp, au nord.",
		["Back to {object:3202}."] = "Retour à {object:3202}.",
		["East of the ogres, Shadowmaw Panthers (37-38) stalk unseen until they strike; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for {npc:2495}.\nCareful: Shadowmaw Panthers (level 37-38) and Elder Shadowmaw Panthers (level 42-43) use Sneak while out of combat, so they remain hidden until you get near them."] = "À l'est des ogres, les Panthères Ombregueule (37-38) rôdent invisibles jusqu'à ce qu'elles frappent ; les Tigresses de Strangleronce parcourent le même terrain et lâchent de temps en temps un croc intact. Les Crocilisques Gueule d'acier bordent la rivière juste à l'ouest de la jungle ; gardez leurs peaux pour {npc:2495}.\nAttention : les Panthères Ombregueule (niveau 37-38) et les Anciennes panthères Ombregueule (niveau 42-43) se camouflent hors combat, elles restent donc cachées jusqu'à ce que vous vous approchiez.",
		["Elder tigers and Lashtail raptors"] = "Anciens tigres et raptors flagellants",
		["Fly to {object:3202}"] = "Prendre un vol pour {object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. From here on, keep every page of {quest:338} you loot: {npc:716} asks for them later."] = "Suivez la route vers le nord depuis {object:3202} ; le camp de chasse de Nesingwary se trouve sur la colline au nord-est de la rivière. Dès maintenant, gardez chaque page de {quest:338} ramassée : {npc:716} les demandera plus tard.",
		["Green Hills pages"] = "Pages des Vertes collines",
		["Level 36"] = "Niveau 36",
		["Mosh'Ogg camp"] = "Camp Mosh'Ogg",
		["Nesingwary's camp"] = "Camp de Nesingwary",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; keep every page you loot and look on the auction house for the rest. {npc:716} takes the chapters later in this guide."] = "Les pages de {item:2755} tombent à environ 1 % chacune sur les trolls Bloodscalp et Skullsplitter ; gardez chaque page ramassée et cherchez le reste à l'hôtel des ventes. {npc:716} prend les chapitres plus loin dans ce guide.",
		["Shadowmaw panthers"] = "Panthères Ombregueule",
		["The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads.\nThe Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a {item:3915}. Keep looting pages of {quest:338}."] = "Les Chasseurs de tête Bloodscalp (36-37) du village sur la côte portent les têtes réduites.\nLes trolls Bloodscalp tiennent les ruines plus haut sur la côte, au nord du récif, et le village au-delà ; chacun peut lâcher un {item:3915}. Continuez à ramasser des pages de {quest:338}.",
		["The Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp; the Lashtail Raptors (35-36) hunt further south, towards {object:3202}.\nCareful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly."] = "Les Anciens tigres de Strangleronce (34-35) parcourent les collines au sud-ouest du camp ; les Raptors flagellants (35-36) chassent plus au sud, vers Grom'gol.\nAttention : des camps trolls sont proches du territoire des tigres, et des trolls peuvent rejoindre le combat si vous attirez sans prudence.",
		["The Lashtail Raptors (35-36) hunt the jungle just north-east of {object:3202}."] = "Les Raptors flagellants (35-36) chassent dans la jungle juste au nord-est de {object:3202}.",
		["The Mosh'Ogg ogres camp in the hills just east of {object:3202}. Kill one Brute and one Witch Doctor (36-37); pull them one at a time."] = "Les ogres Mosh'Ogg campent dans les collines juste à l'est de Grom'gol. Tuez une Brute et un Sorcier-docteur (36-37) ; attirez-les un par un.",
		["The Shadowmaw Panthers (37-38) stalk the jungle east of the Mosh'Ogg hills and north-east towards the lake; they strike from stealth. Loot every Green Hills page you find on the way."] = "Les Panthères Ombregueule (37-38) rôdent dans la jungle à l'est des collines Mosh'Ogg et au nord-est vers le lac ; elles attaquent en camouflage. Ramassez chaque page des Vertes collines trouvée en chemin.",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "Les Panthères Ombregueule viendront bien plus tard, près de {object:3202}",
		["The camp by the river"] = "Le camp près de la rivière",
		["The zeppelin lands at the tower on the west side of the camp."] = "Le zeppelin arrive à la tour à l'ouest du campement.",
		["Underwater"] = "Sous l'eau",
		["Upstairs"] = "À l'étage",
		["Venture Co. camp"] = "Camp de la KapitalRisk",
		["West past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear.\n{npc:729}, a level 37 tiger, prowls the hilltop south-west of the camp.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults."] = "À l'ouest après le camp, des Basilics de cristal (34-35) se tiennent sur les rochers ; chaque Bloodscalp du village plus loin peut lâcher une oreille.\n{npc:729}, un tigre de niveau 37, rôde au sommet de la colline au sud-ouest du camp.\nAttention : le nid de raptors abrite de jeunes raptors qui rejoignent le combat quand vous attaquez les adultes.",
		["Young Stranglethorn Tigers prowl west of the camp, Young Panthers south and east of it.\nHead west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it.\nCareful: The troll camps have many patrolling mobs, so other trolls often join a fight."] = "Les Jeunes tigres de Strangleronce rôdent à l'ouest du camp, les Jeunes panthères au sud et à l'est.\nAllez vers l'ouest après le camp. Les Raptors de Strangleronce (33-34) chassent dans les clairières, et les trolls Bloodscalp tiennent les ruines sur la côte : chaque Bloodscalp peut lâcher une défense. Le {item:4614} est un butin très rare sur eux : si vous en obtenez un, lisez-le.\nAttention : les camps trolls ont de nombreuses patrouilles, d'autres trolls rejoignent donc souvent le combat.",
		["Zeppelin to {object:3202}"] = "Zeppelin pour {object:3202}",
		["grind on {npc:1142}"] = "tuez en boucle : {npc:1142}",
		["{npc:2495}, inside"] = "{npc:2495}, à l'intérieur",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497} : pour les Hautes-terres Arathies, plus loin sur l'itinéraire",
		["{npc:2498}, inside"] = "{npc:2498}, à l'intérieur",
		["{npc:737}, upstairs"] = "{npc:737}, à l'étage",
		["{npc:773}'s missing hunters' camp is Nesingwary's: walk among its tents and the investigation completes. River Crocolisks lie along the river below the camp."] = "Le camp des chasseurs disparus de {npc:773} est celui de Nesingwary : marchez parmi ses tentes et l'enquête est terminée. Des Crocilisques des rivières se trouvent le long de la rivière sous le camp.",
		["{npc:773}, upstairs"] = "{npc:773}, à l'étage",
		["{zone:1434}: kill these as you meet them"] = "{zone:1434} : tuez-les au passage",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Head west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely.\nThe Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes.\nCareful: Darkfang Lurkers (level 36-37) use Sneak to stealth while out of combat and cast Poison once fighting.\nCareful: Stealthed spiders in the same area will attack you on sight.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them."] = "Retraversez le marais vers l'ouest. Les Crache-venin Sombrecroc, sur les crêtes au nord de Fougeraie, lâchent les poches de venin. Les Infiltrateurs de Theramore (35-36) se faufilent dans les mêmes bois : ils sont camouflés, regardez bien.\nLes araignées de Sombrebrume grouillent à l'entrée de la caverne au nord-ouest de Fougeraie ; toutes lâchent des yeux.\nAttention : les Rôdeuses Sombrecroc (niveau 36-37) se camouflent hors combat et lancent Poison une fois en combat.\nAttention : des araignées camouflées dans la même zone vous attaquent à vue.\nAttention : les Rôdeuses de Sombrebrume se déplacent camouflées et utilisent du poison en combat. Les araignées sont serrées les unes contre les autres, les monstres en plus sont donc fréquents ; attirer des cibles isolées depuis le bord extérieur les limite.",
		["Mirefin murlocs"] = "Murlocs Aileron boueux",
		["Shadowprey"] = "Proie-de-l'Ombre",
		["Stinky Ignatz"] = "Ignatz \"Puant\"",
		["Swamp Eye Jarl"] = "Jarl \"Oeil-des-marais\"",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "À l'embranchement, prenez la route du nord jusqu'au village ogre de Mur-de-Fougères.",
		["Underwater"] = "Sous l'eau",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "seulement si vous avez une {item:3853} ({skill:164} ou Hôtel des ventes)",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, pour « Œil-des-marais » Jarl",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}, à l'entrée sud du village, là où arrive la route",
		["{object:20985}, beside the manor"] = "{object:20985}, à côté du manoir",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}, maintenant que {npc:4791} a lu le rapport",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
} end)()
t.guides["forever/horde/30-40/05-arathi-highlands"] = (function() return {
		["Below ground"] = "Sous terre",
		["Fleshstalker raptors"] = "Raptors charognards",
		["Inside"] = "À l'intérieur",
		["North-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael.\nCareful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "Au nord-est de Trépas-d'Orgrim, les kobolds Drywhisker exploitent la gorge ; les Kobolds à l'entrée, et les Fouilleurs et les Géomètres plus loin, lâchent tous des Particules de Myzrael.\nAttention : chaque type de kobold fuit chercher de l'aide quand sa vie est basse (les Kobolds à 30 %, les Géomètres et les Fouilleurs à 15 %), ce qui peut en attirer d'autres.",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "Le cercle intérieur se trouve au sud du cercle ouest, à l'est de Stromgarde.",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701} se trouvent tout au fond de la gorge.",
		["The {object:2702}"] = "{object:2702}",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Entraînez-vous pendant que vous êtes à {zone:1458} : les maîtres se trouvent dans {object:36070}, {object:36073} et {object:36082} (paladins : {npc:260093}).",
		["Underwater"] = "Sous l'eau",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "À l'ouest de la crique, les Ecumeurs ({npc:2595}) et Sorcières Daguéchine (38-40) tiennent le rivage : attirez-les un par un. Les deux épaves gisent dans les hauts-fonds au large, les cartes et journaux à l'intérieur ; les gemmes reposent au fond de la mer autour des épaves.",
		["Zeppelin to {zone:1458}"] = "Zeppelin pour {zone:1458}",
		["{npc:2229}, inside"] = "{npc:2229}, à l'intérieur",
		["{npc:2410}, inside"] = "{npc:2410}, à l'intérieur",
		["{npc:2437}, inside"] = "{npc:2437}, à l'intérieur",
		["{quest:503}, on the top floor"] = "{quest:503}, au dernier étage",
		["{zone:1458} flight master"] = "Maître de vol de {zone:1458}",
		["{zone:1458} trainers"] = "Maîtres de {zone:1458}",
} end)()
t.guides["forever/horde/30-40/06-badlands"] = (function() return {
		["Below ground"] = "Sous terre",
		["Every rock elemental in the {zone:1418} drops {npc:6868}'s shards: the Lesser Rock Elementals (37) on the flats west of {npc:2921}'s camp are the safe ones, about one kill in five. Only the Greater Rock Elementals (42-44, well above you) in the south-western gulches drop {npc:2921}'s bracers, also about one kill in five: pull one at a time and rest between fights, or leave them. Keep killing coyotes and buzzards you still need on the way."] = "Tous les élémentaires de roche des {zone:1418} lâchent les éclats de {npc:6868} : les Élémentaires de roche inférieurs (37), sur les plaines à l'ouest du camp de {npc:2921}, sont les plus sûrs, environ une fois sur cinq. Seuls les Élémentaires de roche supérieurs (42-44, bien au-dessus de vous) dans les ravins du sud-ouest lâchent les brassards de {npc:2921}, également environ une fois sur cinq : attirez-les un par un et reposez-vous entre les combats, ou laissez-les. Continuez à tuer en chemin les coyotes et les busards qui vous manquent encore.",
		["Into the {zone:1418}"] = "Vers {zone:1418}",
		["Lesser Rock Elementals"] = "Elémentaires de roche inférieurs ({npc:2735})",
		["Stonevault troggs"] = "Troggs Stonevault",
		["{npc:2920}: only if you carry {item:2868} ({skill:164} or the Auction House)"] = "{npc:2920} : seulement si vous avez {item:2868} ({skill:164} ou l'hôtel des ventes)",
		["{npc:6868}, inside"] = "{npc:6868}, à l'intérieur",
		["{zone:1418}: kill these as you meet them"] = "{zone:1418} : tuez-les au passage",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "« Loup de mer » MacKinley, au dernier étage",
		["Below ground"] = "Sous terre",
		["Draenethyst crystals"] = "Cristaux de draenéthyste",
		["Fly to {object:3202}"] = "Vol pour {object:3202}",
		["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "Suivez la côte vers le sud. Les explorateurs nagas pataugent le long du rivage et portent les bottes de roseaux ; {object:759} bouillonne dans les collines juste à l'est.",
		["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp."] = "Plus au nord, les gobelins de la KapitalRisk creusent dans la mine à l'est de la route ; mineurs, contremaîtres, géomètres et bricoleurs lâchent tous les cristaux.\nAttention : des Panthères Ombregueule camouflées et des Tigresses de Strangleronce parcourent les environs du camp.",
		["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "Donnez les crocs à Unbagwa et restez près de lui : il appelle trois vagues de gorilles, puis {npc:1514}. Combattez-les un par un.",
		["Head north to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. {npc:1059} guards the south-western ruins, and one pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all."] = "Allez vers le nord jusqu'aux ruines Skullsplitter, à l'est de la mine de la KapitalRisk ; attirez les chasseurs de têtes et les berserkers un par un. {npc:1059} garde les ruines du sud-ouest, et un tas de crânes trophées se trouve du côté nord des ruines. Chaque Skullsplitter peut lâcher une défense ou un collier : les colliers sont la partie lente, alors continuez à tuer dans le camp des guerriers au nord des ruines jusqu'à les avoir tous.",
		["Head north up the road to the hunters' camp."] = "Remontez la route vers le nord jusqu'au camp des chasseurs.",
		["Head north up the road; the hunters camp on the hill above the river."] = "Remontez la route vers le nord ; les chasseurs campent sur la colline au-dessus de la rivière.",
		["Head west to {object:3202}."] = "Allez vers l'ouest jusqu'à Grom'gol.",
		["Inside"] = "À l'intérieur",
		["Jungle Stalkers"] = "Traqueurs de la jungle",
		["Jungle stalkers"] = "Traqueurs de la jungle",
		["Level 42.68"] = "Niveau 42.68",
		["Level 42.74"] = "Niveau 42.74",
		["Mistvale gorillas"] = "Gorilles de Valbrume",
		["Nesingwary's camp"] = "Camp de Nesingwary",
		["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "Au nord-est de Valbrume, les disciples de Zanzil campent dans la jungle ; chacun d'eux peut porter le mélange.",
		["Pirate ghosts"] = "Pirates fantômes",
		["Sawtooth crocolisks"] = "Crocilisques Dents-de-scie",
		["Skullsplitter warriors"] = "Guerriers Skullsplitter",
		["The Bloodsail ships"] = "Les navires de la Voile sanglante",
		["The Jungle Stalkers (40-41) hunt the coast south of {object:3202}. They are well above you: pull one at a time and rest between fights."] = "Les Traqueurs de la jungle (40-41) chassent sur la côte au sud de Grom'gol. Ils sont bien au-dessus de vous : attirez-les un par un et reposez-vous entre les combats.",
		["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "Les gorilles parcourent la vallée autour d'Unbagwa. Les anciens laissent tomber les abats ; tous peuvent laisser tomber un croc.",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "Les raptors traqueurs chassent dans la jungle au sud de {object:3202}, vers la côte ouest.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:728} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:728} est un élite de niveau 40 : la plupart des classes le tuent seules au niveau 42, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:730} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:730} est un élite de niveau 43 : la plupart des classes le tuent seules au niveau 45, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:731} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Tigers and stealthed shadowmaw panthers roam close to him. Clear them before you pull him. When he is pulled, {npc:731} calls for help from creatures within 20 yd."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. Le {npc:731} est un élite de niveau 43 : la plupart des classes le tuent seules au niveau 45, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.\nAttention : des tigres et des panthères Ombregueule camouflées rôdent près de lui. Éliminez-les avant de l'attirer. Une fois attiré, le {npc:731} appelle à l'aide les créatures à moins de 20 m.",
		["Venture Co. mine"] = "Mine de la KapitalRisk",
		["Zanzil's camps"] = "Les camps de Zanzil",
		["Zul'Kunda"] = "Ruines de Zul'Kunda",
		["Zul'Mamwe"] = "Ruines de Zul'Mamwe",
		["grind on {npc:667}"] = "tuez en boucle : {npc:667}",
		["the {object:2076}"] = "le {object:2076}",
		["the {object:2076}, beside {npc:2497}"] = "le {object:2076}, à côté de {npc:2497}",
		["{npc:1442}, upstairs"] = "{npc:1442}, à l'étage",
		["{npc:1443}, on the top floor"] = "{npc:1443}, au dernier étage",
		["{npc:2488}, on the top floor"] = "{npc:2488}, au dernier étage",
		["{npc:2495}: the Snapjaw skins gathered earlier; inside"] = "{npc:2495} : les peaux de Gueule d'acier ramassées plus tôt ; à l'intérieur",
		["{npc:2498}, inside"] = "{npc:2498}, à l'intérieur",
		["{npc:5591}, inside"] = "{npc:5591}, à l'intérieur",
		["{npc:669} walks around here: look inside the circle on the map"] = "{npc:669} se promène par ici : cherchez dans le cercle sur la carte",
		["{npc:6807}, upstairs"] = "{npc:6807}, à l'étage",
		["{npc:6930}, upstairs"] = "{npc:6930}, à l'étage",
		["{npc:737}, upstairs"] = "{npc:737}, à l'étage",
		["{object:3202} flight master"] = "Maître de vol de Grom'gol",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Fly to {object:3202}"] = "Prendre un vol pour {object:3202}",
		["Fly to {zone:1454}. The Droffers brothers run their shop in the Drag.\n{object:172958}, then the {object:172960} and the {object:172961}."] = "Volez jusqu'à {zone:1454}. Les frères Droffers tiennent leur boutique dans la Herse.\n{object:172958}, puis {object:172960} et la {object:172961}.",
		["Grimtotem camp"] = "Camp du Totem sinistre",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "Au nord des gnolls, les ogres tiennent un avant-poste sur une colline ; attirez les Ogres-mages Gordunni vers vous. Le Cobalt Gordunni est dans les tas de terre autour de l'avant-poste, et le Parchemin Gordunni est par terre à l'intérieur.",
		["Ride north-east to the goblin harbour on the coast."] = "Allez au nord-est jusqu'au port gobelin sur la côte.",
		["Riding at 40"] = "Monte au niveau 40",
		["South along the coast, the Southsea pirates hold the cove. {npc:7883} and the stolen cargo are on the docks at its far end. Any pirate can drop a hat, the kidnappers most often.\nCareful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "Au sud le long de la côte, les pirates des Mers du Sud tiennent la crique. {npc:7883} et la cargaison volée sont sur les quais, tout au bout. N'importe quel pirate peut lâcher un chapeau, les kidnappeurs le plus souvent.\nAttention : deux ou trois pirates se tiennent avec {npc:7883}, et beaucoup d'autres pirates de la ville rejoignent le combat une fois qu'il a commencé.",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "Les taurens du Totem sinistre campent à côté du bosquet des Fées fléchetteuses ; Ecumeurs, Naturalistes et Chamans portent tous des Cornes de Totem sinistre.",
		["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane.\nCareful: Every Woodpaw gnoll except the Alpha runs off for help at 15% health, which can pull more gnolls into the fight."] = "Les gnolls Patte-de-bois campent dans les collines juste au nord-ouest de Mojache ; n'importe lequel peut lâcher une crinière.\nAttention : tous les gnolls Patte-de-bois sauf l'Alpha fuient chercher de l'aide à 15 % de vie, ce qui peut attirer d'autres gnolls dans le combat.",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "La ruche des Zukk'ash s'enfonce dans les collines au sud-est du camp ; {quest:7731} attend dans sa chambre la plus profonde.",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "Le Plan de bataille des Griffebois se trouve dans le camp Griffebois au sud de Mojache.",
		["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour.\nCareful: Most Alphas sit in small tent camps with 2-4 other gnolls that join the fight, and other gnolls patrol between the camps."] = "Les fées fléchetteuses voltigent au-dessus du bosquet juste à l'ouest de Mojache ; presque toutes lâchent une aile. Les alphas Patte-de-bois dirigent les camps au sud-ouest : tuez-les dans l'heure.\nAttention : la plupart des Alphas se tiennent dans de petits camps de tentes avec 2 à 4 autres gnolls qui se joignent au combat, et d'autres gnolls patrouillent entre les camps.",
		["Upstairs"] = "À l'étage",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "Loups : {npc:3362}, à côté de {npc:4752}.",
		["Woodpaw battle map"] = "Plan de bataille des Griffebois",
		["Woodpaw north camp"] = "Camp Griffebois du nord",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["for the {zone:1425}, around level 48"] = "pour {zone:1425}, vers le niveau 48",
		["for {zone:1454}, around level 45"] = "pour {zone:1454}, vers le niveau 45",
		["water pouches in your bags"] = "Outres de Bat-le-désert dans vos sacs",
		["{npc:3690}, riding trainer"] = "{npc:3690}, maître de monte",
		["{npc:4752}, riding trainer"] = "{npc:4752}, maître de monte",
		["{npc:7854}, inside"] = "{npc:7854}, à l'intérieur",
		["{npc:7881}, inside"] = "{npc:7881}, à l'intérieur",
		["{npc:7882}, inside"] = "{npc:7882}, à l'intérieur",
		["{npc:7953}, riding trainer"] = "{npc:7953}, maître de monte",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115} : pour {zone:1454}, vers le niveau 45",
		["{quest:2863}: one hour from now"] = "{quest:2863} : dans une heure",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Below ground"] = "Sous terre",
		["Dragon caves"] = "Grottes des dragons",
		["Frayfeather hippogryphs"] = "Hippogryphes Aigreplume",
		["Level 45.41"] = "Niveau 45.41",
		["Murlocs of the Misty Reed"] = "Les murlocs de Misty Reed",
		["Northspring harpies"] = "Harpies Northspring",
		["Onyxia's eggs"] = "Oeufs d'Onyxia",
		["Rage Scar yetis"] = "Yétis Griffe féroce",
		["Ride back north to Brackenwall."] = "Retournez au nord jusqu'à Mur-de-Fougères.",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "Suivez la route vers l'ouest ; le parchemin se trouve au bord de l'eau, à l'extrême ouest du marais.",
		["Riding at 40"] = "Monte au niveau 40",
		["Rogue Vale screechers"] = "Hurleurs des vallées insoumis",
		["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "Des Elémentaires marins et des Embruns longent le rivage autour du quai. Zappez d'abord les géants avec {item:18904} : rétrécis, ils perdent leur force d'élite. Les Marcheurs des rivages pataugent dans l'eau ; les Marcheurs des terres et les Géants des falaises parcourent les collines plus au nord.",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "Au sud du val, les Hippogryphes Aigreplume nichent sur les pentes ; presque tous laissent tomber des Tendons résistants et des Fragments métalliques.",
		["Sprite darters and forest walkers"] = "Fées fléchetteuses et Marcheurs des bois",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "Les Murlocs des marais vivent sur la grève au sud du poste ; les Crache-encre sont le long du rivage à l'est et les Mange-chair plus à l'ouest, autour des huttes de la rive ouest.",
		["The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time."] = "Les harpies Northspring nichent sur les crêtes tout au nord-ouest. Elles sont de niveau 48-50, quelques niveaux au-dessus de vous : les Implorateurs du vent soignent, tuez-les en premier et attirez-les un par un.",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "Les Fées fléchetteuses voltigent au-dessus du bosquet juste à l'ouest du camp et portent les {item:9589} ; les Marcheurs des bois errants, un peu plus à l'ouest, portent les Bûches fendues.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:1173} needs a group of 3. Skip it if you are alone: the route has you grind the XP back.\n{npc:4500} is elite: grouping up is advised. Beat him down until he gives up, then report to {npc:4501}."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {quest:1173} demande un groupe de 3. Passez-la si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.\nLe {npc:4500} est élite : il est conseillé de se grouper. Frappez-le jusqu'à ce qu'il abandonne, puis faites votre rapport à {npc:4501}.",
		["Underwater"] = "Sous l'eau",
		["Zeppelin to {object:3202}"] = "Zeppelin pour {object:3202}",
		["Zeppelin to {zone:1458}"] = "Zeppelin pour {zone:1458}",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "pour l'{npc:5598} dans {zone:1425}, vers le niveau 48",
		["for the {zone:1425} owlbeasts, around level 48"] = "pour les chouettards de {zone:1425}, vers le niveau 48",
		["grind on {npc:4329}"] = "tuez en boucle : {npc:4329}",
		["the {object:2555}"] = "le {object:2555}",
		["{npc:1443}, on the top floor"] = "{npc:1443}, au dernier étage",
		["{npc:4501}, below ground"] = "{npc:4501}, sous terre",
		["{npc:4773}, riding trainer"] = "{npc:4773}, maître de monte",
		["{npc:5591}, inside"] = "{npc:5591}, à l'intérieur",
		["{npc:7825}, the {object:36126}"] = "{npc:7825}, dans le {object:36126}",
		["{npc:7854}, inside"] = "{npc:7854}, à l'intérieur",
		["{object:3202} flight master"] = "Maître de vol de Grom'gol",
		["{quest:7738}, a rare drop"] = "{quest:7738}, butin rare",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Below ground"] = "Sous terre",
		["Dark Iron Lookouts"] = "Guetteurs Sombrefer",
		["Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "Plus au sud, l'équipement du géomètre débutant Scrimshank se trouve à l'entrée d'une ruche Centipaar.\nAttention : un insecte garde l'équipement. De nombreux insectes patrouillent dans les tunnels, certains de niveau 50, les combats attirent donc souvent des monstres en plus.",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "Sa demande suivante exige le {item:10552} sur des cultistes élites : laissez-la.",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "Seulement avec la {item:11818} : retournez à l'est jusqu'aux {object:173265} du site de fouilles.",
		["Scrimshank's gear"] = "Équipement d'analyse de Scrimshank",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "Les Guetteurs Sombrefer se tiennent sur les crêtes autour des tours de guet au sud du Chaudron ; environ un sur dix porte la {item:18960}.",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "Les Forge-vapeur Sombrefer travaillent aux fourneaux au milieu du Chaudron ; la moitié d'entre eux portent une {item:10551}, un sur dix la {item:18959}. Les Esclaves, les Esclavagistes et les Sous-chefs portent aussi des dagues.",
		["The Steamsmiths' furnaces"] = "Les fourneaux des Forge-vapeur",
		["The {object:179827} board"] = "Le panneau {object:179827}",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "À l'ouest de Gadgetzan, utilisez le {item:8584} près du point d'eau du camp troll.",
		["West, the Centipaar insects swarm around their hives; any of them drops the parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you."] = "À l'ouest, les insectes Centipaar grouillent autour de leurs ruches ; n'importe lequel lâche les pièces.\nAttention : les Traînards Centipaar lancent {npc:4196} en combat comme hors combat, ce qui fait venir de petits monstres qui vous interrompent.",
		["for {npc:7010} in {zone:1454}, around level 50"] = "pour {npc:7010} à {zone:1454}, vers le niveau 50",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "la {item:8526} pousse dans {zone:1425}, vers le niveau 48",
		["the {object:173265}"] = "les {object:173265}",
		["{item:11818}, a rare drop"] = "{item:11818}, butin rare",
		["{item:8623}, a rare drop"] = "{item:8623}, butin rare",
		["{npc:5594}, inside"] = "{npc:5594}, à l'intérieur",
		["{npc:5955}'s escort"] = "Escorte de {npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, à côté du maître des coursiers du vent",
		["{quest:3362}: kill these as you meet them"] = "{quest:3362} : tuez-les au passage",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["East of the village, the violet flower grows in the hills."] = "À l'est du village, le Tragan violet pousse dans les collines.",
		["Highvale"] = "Haut-val",
		["Level 49.02"] = "Niveau 49.02",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "Au nord le long de la côte, le panier de pique-nique de {npc:14731} est sur la petite île ; un {npc:14748} le garde.",
		["OOX-09/HL"] = "OOX-09/HL",
		["On the top floor"] = "Au dernier étage",
		["Ride back north to the bloodmages."] = "Retournez au nord jusqu'aux mages de sang.",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "Au sud du gîte, les trolls Witherbark tiennent leurs villages. Chacun porte un crâne : avec vingt crânes, utilisez {item:15002} pour obtenir la Pique de Nimboya préparée, puis plantez-la dans le village.",
		["The big turtles crawl along the beaches north of the village. {npc:2491}'s port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "Les grosses tortues rampent sur les plages au nord du village. Les bouteilles de Porto Pupellyverbos de {npc:2491} se trouvent aussi sur ces plages, mais sa quête ne fait pas partie de cet itinéraire. Une Gueule d'acier des mers peut laisser tomber la Balise de détresse OOX-09/HL, rarement : gardez-la.",
		["The bloodmages"] = "Les mages de sang",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "Leurs quêtes suivantes redemandent les mêmes morceaux pour un objet d'amélioration et ne rapportent pas d'expérience : laissez-les.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} is a level 48 elite: most classes solo it at level 50, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:7977} est un élite de niveau 48 : la plupart des classes le tuent seules au niveau 50, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.",
		["Underwater"] = "Sous l'eau",
		["for {npc:6986} in {zone:1454}, around level 50"] = "pour {npc:6986} à {zone:1454}, vers le niveau 50",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "pour {npc:7825} à {zone:1458}, vers le niveau 50",
		["grind on {npc:2505}"] = "tuez en boucle : {npc:2505}",
		["{item:8704}, a rare drop"] = "{item:8704}, butin rare",
		["{npc:14731}'s lunch"] = "Le repas de {npc:14731}",
		["{npc:14731}, inside"] = "{npc:14731}, à l'intérieur",
		["{npc:7801}'s camp"] = "Camp de {npc:7801}",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "« Loup de mer » MacKinley, au dernier étage",
		["Back north-east to {npc:8420}."] = "Retournez au nord-est voir {npc:8420}.",
		["Back to {object:3202}"] = "Retour à {object:3202}",
		["Below ground"] = "Sous terre",
		["Class trainer"] = "Maître de classe",
		["Fly to {object:3202}"] = "Prendre un vol pour {object:3202}",
		["Frayfeather Hippogryphs"] = "Hippogryphes Aigreplume",
		["Ironjaw Basilisks"] = "Basilics gueule de fer",
		["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "Gardez les livraisons pour {npc:4046}, {npc:8659} et {npc:6522} : vous passerez plus tard par {zone:1456}, {zone:1454} et {zone:1458}.",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "Gardez {quest:3444} : le coffre de {npc:7771} s'ouvre lors d'une visite ultérieure.",
		["Only once all three robots are home"] = "Seulement une fois les trois robots rentrés",
		["Paladin trainer"] = "Maître des paladins",
		["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "Allez au sud-ouest jusqu'aux ruines. Les quatre tablettes s'y trouvent, gardées par les nagas Fouette-bile ; toute Sirène ou tout Myrmidon Fouette-bile peut porter la rune de {npc:8420}.",
		["Sprite Darters"] = "Fées fléchetteuses",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "Les fantômes bien-nés hantent les ruines juste au nord du sanctuaire ; les satyres Haldarr campent un peu plus au nord.",
		["The Sea Elementals and Sea Sprays wash along the shore around the dock.\nThe Land Walkers and Cliff Giants roam the hills north of the dock. Zap each one with {item:18904} first: shrunken, they are no longer elite. Every zapped giant drops residue; use the Muisek Vessel on its body too."] = "Les Élémentaires marins et les Embruns ondoient le long du rivage autour du quai.\nLes Marcheurs des terres et les Géants des falaises parcourent les collines au nord du quai. Frappez d'abord chacun avec l'{item:18904} : une fois rapetissés, ils ne sont plus élites. Chaque géant rapetissé lâche du résidu ; utilisez aussi le Récipient de Muisek sur son corps.",
		["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "Le camp des elfes de sang se trouve juste au sud de {npc:8420}. Ses quatre pièces d'équipement sont dans les caisses autour du camp.",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "Les dragons féériques voltigent dans les bois juste à l'ouest du camp. Utilisez le récipient sur chacun de ceux que vous tuez.",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "Les hippogryphes nichent sur les collines au sud-ouest du camp. Tuez-en un, puis utilisez le récipient miniaturisé sur son corps.",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "Les tréants errent sur les routes forestières entre le camp et le centre de {zone:1444} ; ils sont peu nombreux, cherchez le long des chemins.",
		["The {object:2076} beside {npc:2519}"] = "Le {object:2076} à côté de {npc:2519}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:818} (level 47 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back.\nCareful: Two elite caster guards, around level 45, stand with {npc:818} and join the fight together with him."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:818} (élite de niveau 47) demande un groupe de 2. Passez-le si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.\nAttention : deux gardes élites lanceurs de sorts, autour du niveau 45, se tiennent avec {npc:818} et se joignent au combat avec lui.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:8552} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {quest:8552} demande un groupe de 2. Passez-la si vous êtes seul : la route vous fait regagner cette expérience en tuant des monstres.",
		["To {object:3202}"] = "Vers {object:3202}",
		["Undamaged Hippogryph Feathers"] = "Plumes d'hippogryphe sans défaut",
		["Upstairs"] = "À l'étage",
		["Wandering Forest Walkers"] = "Marcheurs des bois errants",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["grind on {npc:6125}"] = "tuez en boucle : {npc:6125}",
		["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{npc:246344} aux {zone:1456} ; {zone:1454} n'a pas de maître des paladins",
		["{npc:5594}, inside"] = "{npc:5594}, à l'intérieur",
		["{npc:6986}, the Drag"] = "{npc:6986}, la Herse",
		["{npc:7406}, inside"] = "{npc:7406}, à l'intérieur",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776} : les ours sont à {zone:1448}",
		["{npc:7876}'s tar and Pestlezugg's samples come from {zone:1449}."] = "Le goudron de {npc:7876} et les échantillons de l'Alchimiste Pestlezugg viennent de {zone:1449}.",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, à côté du maître des coursiers du vent",
		["{npc:8395}, at the east edge of the camp: no experience, only a teleport to Azshara Tower"] = "{npc:8395}, à la lisière est du camp : pas d'expérience, seulement une téléportation vers la tour d'Azshara",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{object:3202} flight master"] = "Maître de vol de Grom'gol",
		["{quest:3761} is gathered in the next guide; {npc:4046}'s payment goes back to {npc:8587} later."] = "{quest:3761} se récolte dans le guide suivant ; le paiement de {npc:4046} retourne à {npc:8587} plus tard.",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
		["{zone:1456} flight master"] = "Maître de vol des {zone:1456}",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Below ground"] = "Sous terre",
		["Careful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd."] = "Attention : les Ouvriers Gorishi qui passent sous 45 % de vie ont 50 % de chances d'appeler à l'aide leurs alliés à moins de 25 m.",
		["Careful: There are many ravasaurs roaming the area, so you can easily pull several at the same time."] = "Attention : de nombreux ravasaures parcourent la zone, il est donc facile d'en attirer plusieurs à la fois.",
		["Careful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "Attention : l'{npc:10411} devient invisible hors combat et appelle des Gargouilles Aile-de-roc dès qu'un combat commence. Il n'en existe que 3, et elles réapparaissent toutes les 15 minutes.",
		["Cross the south of the crater to the pylon on the western cliffs."] = "Traversez le sud du cratère jusqu'au pylône sur les falaises de l'ouest.",
		["Eastern Pylon"] = "Pylône est",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "Longez les falaises vers le sud jusqu'au {quest:3821}, la colline des ogres Brûlentrailles. Les restes de {npc:9136} gisent à son pied.",
		["Free Darrowshire Spirits: talk to them"] = "Libérez des Esprits de Darrowshire ({npc:11064}) : parlez-leur",
		["From here on pick up every Power Crystal (blue, green, red, yellow) and every {quest:3761} pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."] = "Dès maintenant, ramassez chaque Cristal de puissance (bleu, vert, rouge, jaune) et chaque tas de {quest:3761} sur votre route : 25 terres en tout, 20 pour Hamuul et 5 pour Pestlezugg.",
		["Gorillas"] = "Gorilles",
		["Inside"] = "À l'intérieur",
		["Into the {zone:1427}"] = "Vers la {zone:1427}",
		["Keep the parcel: {npc:10781} is in the {zone:1458}."] = "Gardez le colis : le {npc:10781} est à {zone:1458}.",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "Gardez la quête {quest:4147} de {npc:9118} et la lettre de {npc:8737} pour des guides ultérieurs.",
		["Lar'korwi Mates"] = "Compagnes de Lar'korwi ({npc:9683})",
		["Lashers and Threshers"] = "Flagellants et Batteurs",
		["Level 52"] = "Niveau 52",
		["North of Torwa, a dead Threshadon lies by the water."] = "Au nord de Torwa, un battrodon mort gît au bord de l'eau.",
		["Northern Pylon"] = "Pylône nord",
		["Out of the refuge"] = "Hors du refuge",
		["Power Crystals and soil"] = "Cristaux de puissance et terre",
		["Pterrordax"] = "Pterreurdactyles",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "Descendez le côté est du cratère jusqu'au pylône sur les falaises de l'est.",
		["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "Allez vers le nord le long du côté est. Les Flagellants et les Batteurs Pétale-de-sang remplissent la jungle.",
		["Scarlet forward camp"] = "Camp avancé écarlate",
		["Stegodons and ravasaurs"] = "Stégodons et ravasaures",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5401}: Scourgestones only drop while you wear it."] = "Prenez une {object:176092} dans la caisse à côté de Derrington pour {quest:5096}, à faire au retour. Équipez la {quest:5401} : les Pierres du Fléau ne tombent que si vous la portez.",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "Les Compagnes de Lar'korwi ({npc:9683}) rôdent dans la jungle au nord-ouest de {npc:9619}.",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "La tête de la poupée et ses deux côtés sont dans les maisons autour de {npc:10926} ; assemblez-les depuis vos sacs.",
		["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "La caisse de l'expédition se trouve dans un camp abandonné de la jungle de l'est.",
		["The expedition's lost equipment lies in the south-west jungle."] = "L'équipement perdu de l'expédition se trouve dans la jungle du sud-ouest.",
		["The gorillas live on the north-east plateau. Stay out of the deepest cave: {npc:9622} lives there."] = "Les gorilles vivent sur le plateau du nord-est. N'entrez pas dans la grotte la plus profonde : {npc:9622} y vit.",
		["The next guide starts here, at the chapel's flight master."] = "Le guide suivant commence ici, au maître de vol de la chapelle.",
		["The pylon stands on the slope east of the refuge."] = "Le pylône se dresse sur la pente à l'est du refuge.",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "Le radeau est sur la rive du lac du sud-est ; le petit paquetage est dans l'eau à côté.",
		["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the {item:11834}."] = "Les fosses de goudron se trouvent juste au sud du refuge. Les Bêtes du goudron, les Rôdeurs et les Rampants lâchent le {item:11834}.",
		["Underwater"] = "Sous l'eau",
		["Upstairs"] = "À l'étage",
		["Use the Mangled Journal to start it"] = "Utilisez Un journal abîmé pour la commencer",
		["Western Pylon"] = "Pylône ouest",
		["grind on Pterrordax"] = "tuez en boucle : ptérreurdactyles",
		["grind on {npc:6509}"] = "tuez en boucle : {npc:6509}",
		["grind on {npc:6511}"] = "tuez en boucle : {npc:6511}",
		["grind on {npc:6551}"] = "tuez en boucle : {npc:6551}",
		["{item:11116}, a rare drop"] = "{item:11116}, butin rare",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}, {object:36078}, près du maître des chauves-souris",
		["{npc:5594}, inside"] = "{npc:5594}, à l'intérieur",
		["{npc:6522}, the {object:36073}"] = "{npc:6522}, {object:36073}",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825} se tient dans le {object:36082}.",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}, l'Apothicarium : les fioles se remplissent plus tard en {zone:1447}",
		["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}, au fond de la grotte ; sous terre",
		["{npc:9117}, below ground"] = "{npc:9117}, sous terre",
		["{npc:9618}, just outside"] = "{npc:9618}, juste dehors",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619} campe dans le coin sud-est du cratère.",
		["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "{npc:9623} veut ensuite une {item:10561}, un objet d'{skill:202}. Passez cette quête sauf si vous en avez une.",
		["{npc:9623}, the robot on the plateau; below ground"] = "{npc:9623}, le robot sur le plateau ; sous terre",
		["{npc:9998}, at the entrance"] = "{npc:9998}, à l'entrée",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, à l'entrée du refuge",
		["{object:175894}, beside the house; inside"] = "{object:175894}, à côté de la maison ; à l'intérieur",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822} arpente les grottes et galeries de mine du {quest:3821} ; s'il est absent, tuez les ogres autour des entrées jusqu'à son retour.",
		["{zone:1454} flight master"] = "Maître de vol d'{zone:1454}",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Below ground"] = "Sous terre",
		["Careful: Den Watchers are level 53-54; they call nearby allies within 25 yd once below 50% health and run off for help below 15%."] = "Attention : les Protecteurs Mort-bois sont de niveau 53-54 ; ils appellent leurs alliés à moins de 25 m sous 50 % de vie et fuient chercher de l'aide sous 15 %.",
		["Class trainer"] = "Maître de classe",
		["Derrington's watchtowers, Vandis' cauldron and {npc:11615}'s barrel are done on a later visit: keep them."] = "Les tours de guet de Derrington, le chaudron de Vandis et le tonneau de {npc:11615} se font lors d'une visite ultérieure : gardez-les.",
		["Diseased Grizzlies"] = "Grizzlys malades",
		["Diseased Wolves"] = "Loups malades",
		["Druid trainer"] = "Maître des druides",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "À l'est du Poste de la Vénéneuse, le val criblé de cratères où errent les Bêtes d'entropie et les Horreurs. Tuez-en deux de chaque, puis allez à chacun des trois cratères d'eau gangrenée.",
		["Inside"] = "À l'intérieur",
		["Jadefire moonwell"] = "Puits de lune des Jadefeu",
		["Keep the branch: {npc:5770} is in {zone:1456}."] = "Gardez la branche : {npc:5770} est à {zone:1456}.",
		["Keep {quest:5158}: {npc:5901} is in the {zone:1413}."] = "Gardez {quest:5158} : {npc:5901} est dans {zone:1413}.",
		["Keep {quest:8465} for {zone:1452}."] = "Gardez {quest:8465} pour {zone:1452}.",
		["Level 52.63"] = "Niveau 52.63",
		["Level 53.02"] = "Niveau 53.02",
		["Level 53.2"] = "Niveau 53.2",
		["Level 53.34"] = "Niveau 53.34",
		["Level 54.1"] = "Niveau 54.1",
		["Level 54.45"] = "Niveau 54.45",
		["Level 54.54"] = "Niveau 54.54",
		["Level 54.7"] = "Niveau 54.7",
		["Level 54.87"] = "Niveau 54.87",
		["Northern crater"] = "Cratère nord",
		["Only with 5 Deadwood Headdress Feathers"] = "Seulement avec 5 Coiffures de plumes mort-bois ({item:21377})",
		["Paladin trainer"] = "Maître des paladins",
		["Ride north up the road again."] = "Remontez la route vers le nord.",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "Chevauchez vers le nord-ouest jusqu'à Andorhal. {npc:10667} attend dans l'auberge en ruine à l'ouest de la ville ; les squelettes à l'intérieur sont de niveau 54-57, restez donc sur les bords.",
		["Scarlet Crusade"] = "Croisade écarlate",
		["Southern crater"] = "Cratère sud",
		["Take the kitten to the same moonwell and release it there; once it has turned into a {npc:10042}, bring it back to {npc:9996} and click on it to hand it over."] = "Emmenez le chaton au même puits de lune et relâchez-le là ; une fois changé en {npc:10042}, ramenez-le à {npc:9996} et cliquez dessus pour le lui remettre.",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one."] = "Les annales se trouvent parmi les Tomes moisis ({object:176150}) de l'hôtel de ville d'Andorhal ; ouvrez-les jusqu'à trouver le bon.",
		["The Deadwood furbolg village just west of the tunnel. {npc:9462} (56) stands among them. {npc:11557}, a friendly furbolg, sits at the north end of the village."] = "Le village des furbolgs Mort-bois juste à l'ouest du tunnel. {npc:9462} (56) se tient parmi eux. {npc:11557}, un furbolg amical, est assis à l'extrémité nord du village.",
		["The Jadefire moonwell"] = "Le puits de lune des Jadefeu",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "Le journal se trouve dans la ferme, le meuble est à l'intérieur et les latrines sont derrière. Un {npc:10816} porte la clé des latrines ; {npc:10836} sort quand vous ouvrez les latrines et porte la clé du meuble.",
		["The druids' camp is just past the border."] = "Le camp des druides se trouve juste après la frontière.",
		["Upstairs"] = "À l'étage",
		["Western crater"] = "Cratère ouest",
		["Zeppelin to {zone:1454}"] = "Zeppelin pour {zone:1454}",
		["grind on {npc:10605}"] = "tuez en boucle : {npc:10605}",
		["grind on {npc:1816}"] = "tuez en boucle : {npc:1816}",
		["grind on {npc:1817}"] = "tuez en boucle : {npc:1817}",
		["grind on {npc:1826}"] = "tuez en boucle : {npc:1826}",
		["grind on {npc:7101}"] = "tuez en boucle : {npc:7101}",
		["grind on {npc:7125}"] = "tuez en boucle : {npc:7125}",
		["grind on {npc:7153}"] = "tuez en boucle : {npc:7153}",
		["grind on {npc:7155}"] = "tuez en boucle : {npc:7155}",
		["grind on {npc:7156}"] = "tuez en boucle : {npc:7156}",
		["grind on {npc:8957}"] = "tuez en boucle : {npc:8957}",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306} : les chouettards sont à {zone:1452}",
		["{npc:10840}, at the graveyard's south end"] = "{npc:10840}, à l'extrémité sud du cimetière",
		["{npc:10927}'s house stands by the road, and {npc:10936}'s monument is in the graveyard behind it."] = "La maison de {npc:10927} se trouve au bord de la route, et le monument de {npc:10936} est dans le cimetière derrière.",
		["{npc:10927}, upstairs"] = "{npc:10927}, à l'étage",
		["{npc:11016}, below ground"] = "{npc:11016}, sous terre",
		["{npc:11020}, below ground"] = "{npc:11020}, sous terre",
		["{npc:11554}, at the south edge of the camp"] = "{npc:11554}, à la lisière sud du camp",
		["{npc:11557}: keep 30 {quest:6031} for him; he trades only at Neutral with the Timbermaw; below ground"] = "{npc:11557} : gardez 30 {quest:6031} pour lui ; il n'échange qu'à partir de Neutre auprès des Grumegueules ; sous terre",
		["{npc:1855}'s hunts are in the {zone:1423}: keep them for later."] = "Les chasses de {npc:1855} se font dans les {zone:1423} : gardez-les pour plus tard.",
		["{npc:3034} in {zone:1412}; {zone:1454} has no druid trainer"] = "{npc:3034} ({zone:1412}) ; {zone:1454} n'a pas de maître des druides",
		["{npc:9529}, just west of the camp"] = "{npc:9529}, juste à l'ouest du camp",
		["{npc:9529}, on the west side of the Sanctuary"] = "{npc:9529}, à l'ouest du Sanctuaire",
		["{npc:9996}'s kitten"] = "Le chaton de {npc:9996}",
		["{object:175924}, inside"] = "{object:175924}, à l'intérieur",
		["{quest:5058}, inside"] = "{quest:5058}, à l'intérieur",
